import os
from typing import Any, Dict, Optional
from urllib.parse import urlencode

import requests

AUTH0_DOMAIN = os.getenv("AUTH0_DOMAIN")
AUTH0_CLIENT_ID = os.getenv("AUTH0_CLIENT_ID")
AUTH0_CLIENT_SECRET = os.getenv("AUTH0_CLIENT_SECRET")
AUTH0_REDIRECT_URI = os.getenv("AUTH0_REDIRECT_URI")
AUTH0_AUDIENCE = os.getenv("AUTH0_AUDIENCE")

AUTH0_TOKEN_URL = f"https://{AUTH0_DOMAIN}/oauth/token" if AUTH0_DOMAIN else None
AUTH0_USERINFO_URL = f"https://{AUTH0_DOMAIN}/userinfo" if AUTH0_DOMAIN else None
AUTH0_AUTHORIZE_URL = f"https://{AUTH0_DOMAIN}/authorize" if AUTH0_DOMAIN else None


def build_authorization_url(state: str, scope: str = "openid profile email", prompt: Optional[str] = None) -> str:
    if not AUTH0_AUTHORIZE_URL or not AUTH0_CLIENT_ID or not AUTH0_REDIRECT_URI:
        raise ValueError("Missing required Auth0 configuration: AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_REDIRECT_URI")

    params = {
        "client_id": AUTH0_CLIENT_ID,
        "response_type": "code",
        "redirect_uri": AUTH0_REDIRECT_URI,
        "scope": scope,
        "state": state,
    }
    if AUTH0_AUDIENCE:
        params["audience"] = AUTH0_AUDIENCE
    if prompt:
        params["prompt"] = prompt

    return f"{AUTH0_AUTHORIZE_URL}?{urlencode(params)}"


def exchange_code_for_tokens(code: str, redirect_uri: Optional[str] = None) -> Dict[str, Any]:
    if not AUTH0_TOKEN_URL or not AUTH0_CLIENT_ID or not AUTH0_CLIENT_SECRET:
        raise ValueError(
            "Missing required Auth0 configuration: AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET"
        )

    payload = {
        "grant_type": "authorization_code",
        "client_id": AUTH0_CLIENT_ID,
        "client_secret": AUTH0_CLIENT_SECRET,
        "code": code,
        "redirect_uri": redirect_uri or AUTH0_REDIRECT_URI,
    }
    if not payload["redirect_uri"]:
        raise ValueError("Missing redirect_uri; set AUTH0_REDIRECT_URI or pass redirect_uri")

    response = requests.post(
        AUTH0_TOKEN_URL,
        json=payload,
        headers={"Content-Type": "application/json"},
        timeout=15,
    )
    response.raise_for_status()
    return response.json()


def fetch_userinfo(access_token: str) -> Dict[str, Any]:
    if not AUTH0_USERINFO_URL:
        raise ValueError("Missing required Auth0 configuration: AUTH0_DOMAIN")

    response = requests.get(
        AUTH0_USERINFO_URL,
        headers={"Authorization": f"Bearer {access_token}"},
        timeout=15,
    )
    response.raise_for_status()
    return response.json()


def handle_callback(query_params: Dict[str, str]) -> Dict[str, Any]:
    error = query_params.get("error")
    if error:
        return {
            "ok": False,
            "error": error,
            "error_description": query_params.get("error_description"),
            "state": query_params.get("state"),
        }

    code = query_params.get("code")
    if not code:
        return {"ok": False, "error": "missing_code", "error_description": "Authorization code not present in callback"}

    tokens = exchange_code_for_tokens(code, redirect_uri=query_params.get("redirect_uri"))
    result: Dict[str, Any] = {"ok": True, "tokens": tokens}

    access_token = tokens.get("access_token")
    if access_token:
        try:
            result["userinfo"] = fetch_userinfo(access_token)
        except requests.RequestException:
            result["userinfo"] = None

    return result
